PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, sort_order INTEGER NOT NULL DEFAULT 0, is_promo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS subcategories (id INTEGER PRIMARY KEY AUTOINCREMENT, category_name TEXT NOT NULL, name TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, UNIQUE(category_name, name));
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, sub TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL DEFAULT '', price INTEGER NOT NULL DEFAULT 0, soldout INTEGER NOT NULL DEFAULT 0, photo TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS pack_options (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id TEXT NOT NULL, label TEXT NOT NULL, price INTEGER, step REAL NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_pack_options_product ON pack_options(product_id, sort_order);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category, sub, sort_order);
CREATE TABLE IF NOT EXISTS admin_credentials (id INTEGER PRIMARY KEY CHECK(id = 1), salt TEXT NOT NULL, hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS admin_sessions (token_hash TEXT PRIMARY KEY, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
